SourceCode.Declaration:
/// <summary>
/// Logic Class used for outputting a value from the context
/// </summary>
[TFMDescription("Takes a value from the context and outputs it")]
class TFMLogicContextFieldValue extends TFMLogicContextObject
{
}

Method.Source:
protected void new()
{
    super();

    outputType = TFMLogicContextTypes::String;
    noOfInput = 0;
    categories.add("Data");
}

public Name Name()
{
    return "Value from Context";
}

public Object process(TFMFlowVariableContextLookupField _value = '', NoYesId _valuesNotFoundInContextIsDiscarded = NoYes::No)
{

    Map	    resultMap = new Map(Types::String, Types::String);
    str     inputValue;

    if (_value)
    {
        inputValue = context.replaceWithValue(_value);
    }

    if(_valuesNotFoundInContextIsDiscarded && _value == inputValue)
    {
        // do nothing
    } 
    else
    {
        resultMap.insert('', inputValue); // When no key is specified, return the result with an empty string key
    }


    return resultMap;
}
